-- Easycut state.sqlite v1 schema
-- IDs are UUID-style TEXT values generated by the application.
-- Timestamps are RFC 3339 UTC TEXT values. Durations/timestamps within media
-- are INTEGER microseconds.

PRAGMA foreign_keys = ON;

CREATE TABLE database_schema_version (
    singleton_id INTEGER NOT NULL PRIMARY KEY CHECK (singleton_id = 1),
    version INTEGER NOT NULL CHECK (version >= 1),
    migration_id TEXT NOT NULL,
    updated_at TEXT NOT NULL
) WITHOUT ROWID;

CREATE TABLE schema_migration (
    version INTEGER NOT NULL PRIMARY KEY,
    migration_id TEXT NOT NULL UNIQUE,
    checksum TEXT NOT NULL,
    applied_at TEXT NOT NULL
) WITHOUT ROWID;

INSERT INTO database_schema_version (singleton_id, version, migration_id, updated_at)
VALUES (1, 1, '0001_initial', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));

INSERT INTO schema_migration (version, migration_id, checksum, applied_at)
VALUES (1, '0001_initial', 'documentation-defined', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));

-- --------------------------------------------------------------------------
-- Durable project and source state
-- --------------------------------------------------------------------------

CREATE TABLE project (
    id TEXT NOT NULL PRIMARY KEY,
    name TEXT NOT NULL DEFAULT 'Untitled Project',
    format_version TEXT NOT NULL,
    app_min_version TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    last_opened_at TEXT
) WITHOUT ROWID;

CREATE TABLE recording_session (
    id TEXT NOT NULL PRIMARY KEY,
    project_id TEXT NOT NULL UNIQUE,
    title TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (project_id) REFERENCES project(id) ON DELETE CASCADE
) WITHOUT ROWID;

-- Immutable source identity and original media metadata.
CREATE TABLE source_clip (
    id TEXT NOT NULL PRIMARY KEY,
    project_id TEXT NOT NULL,
    original_filename TEXT NOT NULL,
    original_path_hint TEXT,
    original_capture_at TEXT,
    imported_at TEXT NOT NULL,
    source_fingerprint TEXT NOT NULL,
    fingerprint_algorithm TEXT NOT NULL,
    file_size_bytes INTEGER CHECK (file_size_bytes IS NULL OR file_size_bytes >= 0),
    duration_us INTEGER NOT NULL CHECK (duration_us > 0),
    width_px INTEGER CHECK (width_px IS NULL OR width_px > 0),
    height_px INTEGER CHECK (height_px IS NULL OR height_px > 0),
    frame_rate_num INTEGER CHECK (frame_rate_num IS NULL OR frame_rate_num > 0),
    frame_rate_den INTEGER CHECK (frame_rate_den IS NULL OR frame_rate_den > 0),
    audio_sample_rate_hz INTEGER CHECK (audio_sample_rate_hz IS NULL OR audio_sample_rate_hz > 0),
    audio_channel_count INTEGER CHECK (audio_channel_count IS NULL OR audio_channel_count > 0),
    media_type TEXT NOT NULL DEFAULT 'movie',
    FOREIGN KEY (project_id) REFERENCES project(id) ON DELETE CASCADE,
    UNIQUE (project_id, source_fingerprint, fingerprint_algorithm)
) WITHOUT ROWID;

-- Current mutable local resolution/availability; does not change source identity.
CREATE TABLE source_clip_location (
    source_clip_id TEXT NOT NULL PRIMARY KEY,
    local_path_hint TEXT,
    security_scope_bookmark BLOB,
    availability_status TEXT NOT NULL CHECK (availability_status IN ('available', 'missing', 'ambiguous', 'unvalidated')),
    validated_fingerprint TEXT,
    validated_fingerprint_algorithm TEXT,
    last_checked_at TEXT,
    last_validation_error TEXT,
    updated_at TEXT NOT NULL,
    CHECK (availability_status <> 'available' OR validated_fingerprint IS NOT NULL),
    FOREIGN KEY (source_clip_id) REFERENCES source_clip(id) ON DELETE CASCADE
) WITHOUT ROWID;

-- Append-only relink audit; source_clip.id never changes.
CREATE TABLE source_relink_event (
    id TEXT NOT NULL PRIMARY KEY,
    source_clip_id TEXT NOT NULL,
    action TEXT NOT NULL CHECK (action IN ('initial_import', 'relink_attempt', 'validation', 'marked_missing')),
    previous_path_hint TEXT,
    new_path_hint TEXT,
    observed_fingerprint TEXT,
    observed_fingerprint_algorithm TEXT,
    result TEXT NOT NULL CHECK (result IN ('matched', 'mismatched', 'ambiguous', 'missing', 'unvalidated')),
    details_json TEXT,
    created_at TEXT NOT NULL,
    FOREIGN KEY (source_clip_id) REFERENCES source_clip(id) ON DELETE CASCADE
) WITHOUT ROWID;

-- Immutable snapshot of the confirmed clip order for an analysis run.
CREATE TABLE sequence_revision (
    id TEXT NOT NULL PRIMARY KEY,
    recording_session_id TEXT NOT NULL,
    revision_number INTEGER NOT NULL CHECK (revision_number >= 1),
    status TEXT NOT NULL CHECK (status IN ('draft', 'confirmed', 'superseded')),
    source_sequence_hash TEXT NOT NULL,
    creation_reason TEXT NOT NULL,
    created_by TEXT NOT NULL CHECK (created_by IN ('system', 'creator')),
    created_at TEXT NOT NULL,
    confirmed_at TEXT,
    FOREIGN KEY (recording_session_id) REFERENCES recording_session(id) ON DELETE CASCADE,
    UNIQUE (recording_session_id, revision_number)
) WITHOUT ROWID;

-- One row per imported clip in a sequence revision. Exclusion is reversible.
CREATE TABLE sequence_membership (
    id TEXT NOT NULL PRIMARY KEY,
    sequence_revision_id TEXT NOT NULL,
    source_clip_id TEXT NOT NULL,
    ordinal INTEGER NOT NULL CHECK (ordinal >= 0),
    membership_status TEXT NOT NULL CHECK (membership_status IN ('active', 'excluded')),
    inferred_order_rank INTEGER,
    order_confirmed_by_creator INTEGER NOT NULL DEFAULT 0 CHECK (order_confirmed_by_creator IN (0, 1)),
    ordering_evidence_json TEXT,
    created_at TEXT NOT NULL,
    FOREIGN KEY (sequence_revision_id) REFERENCES sequence_revision(id) ON DELETE CASCADE,
    FOREIGN KEY (source_clip_id) REFERENCES source_clip(id) ON DELETE CASCADE,
    UNIQUE (sequence_revision_id, source_clip_id),
    UNIQUE (sequence_revision_id, ordinal)
) WITHOUT ROWID;

-- --------------------------------------------------------------------------
-- Transcription and transcript correction state
-- --------------------------------------------------------------------------

CREATE TABLE transcription_run (
    id TEXT NOT NULL PRIMARY KEY,
    recording_session_id TEXT NOT NULL,
    sequence_revision_id TEXT NOT NULL,
    audio_input_fingerprint TEXT NOT NULL,
    language_code TEXT NOT NULL,
    model_provider TEXT NOT NULL,
    model_name TEXT NOT NULL,
    configuration_version TEXT NOT NULL,
    lifecycle_state TEXT NOT NULL CHECK (lifecycle_state IN ('requested', 'processing', 'sealed', 'failed')),
    requested_at TEXT NOT NULL,
    sealed_at TEXT,
    error_code TEXT,
    error_message TEXT,
    FOREIGN KEY (recording_session_id) REFERENCES recording_session(id) ON DELETE CASCADE,
    FOREIGN KEY (sequence_revision_id) REFERENCES sequence_revision(id) ON DELETE CASCADE,
    CHECK (lifecycle_state <> 'sealed' OR sealed_at IS NOT NULL)
) WITHOUT ROWID;

-- Immutable once inserted with sealed_at. Downstream runs reference this row.
CREATE TABLE transcript_version (
    id TEXT NOT NULL PRIMARY KEY,
    transcription_run_id TEXT NOT NULL UNIQUE,
    sequence_revision_id TEXT NOT NULL,
    version_number INTEGER NOT NULL CHECK (version_number >= 1),
    language_code TEXT NOT NULL,
    completeness TEXT NOT NULL CHECK (completeness IN ('complete', 'partial')),
    source_audio_fingerprint TEXT NOT NULL,
    model_provider TEXT NOT NULL,
    model_name TEXT NOT NULL,
    configuration_version TEXT NOT NULL,
    created_at TEXT NOT NULL,
    sealed_at TEXT NOT NULL,
    FOREIGN KEY (transcription_run_id) REFERENCES transcription_run(id) ON DELETE CASCADE,
    FOREIGN KEY (sequence_revision_id) REFERENCES sequence_revision(id) ON DELETE CASCADE,
    UNIQUE (sequence_revision_id, version_number)
) WITHOUT ROWID;

-- Immutable version-scoped speech units.
CREATE TABLE utterance (
    id TEXT NOT NULL PRIMARY KEY,
    transcript_version_id TEXT NOT NULL,
    ordinal INTEGER NOT NULL CHECK (ordinal >= 0),
    recognized_text TEXT NOT NULL,
    language_code TEXT NOT NULL,
    created_at TEXT NOT NULL,
    FOREIGN KEY (transcript_version_id) REFERENCES transcript_version(id) ON DELETE CASCADE,
    UNIQUE (transcript_version_id, ordinal)
) WITHOUT ROWID;

-- A speech unit can map to one or more clip-local ranges.
CREATE TABLE utterance_source_range (
    id TEXT NOT NULL PRIMARY KEY,
    utterance_id TEXT NOT NULL,
    range_ordinal INTEGER NOT NULL CHECK (range_ordinal >= 0),
    source_clip_id TEXT NOT NULL,
    start_us INTEGER NOT NULL CHECK (start_us >= 0),
    end_us INTEGER NOT NULL CHECK (end_us > start_us),
    FOREIGN KEY (utterance_id) REFERENCES utterance(id) ON DELETE CASCADE,
    FOREIGN KEY (source_clip_id) REFERENCES source_clip(id) ON DELETE CASCADE,
    UNIQUE (utterance_id, range_ordinal)
) WITHOUT ROWID;

-- Word-level timing/alignment retained for precision, not primary UI editing.
CREATE TABLE word_alignment (
    id TEXT NOT NULL PRIMARY KEY,
    utterance_id TEXT NOT NULL,
    token_index INTEGER NOT NULL CHECK (token_index >= 0),
    token_text TEXT NOT NULL,
    source_clip_id TEXT NOT NULL,
    start_us INTEGER NOT NULL CHECK (start_us >= 0),
    end_us INTEGER NOT NULL CHECK (end_us > start_us),
    confidence REAL CHECK (confidence IS NULL OR (confidence >= 0.0 AND confidence <= 1.0)),
    token_kind TEXT NOT NULL DEFAULT 'word' CHECK (token_kind IN ('word', 'punctuation', 'filler', 'unknown')),
    FOREIGN KEY (utterance_id) REFERENCES utterance(id) ON DELETE CASCADE,
    FOREIGN KEY (source_clip_id) REFERENCES source_clip(id) ON DELETE CASCADE,
    UNIQUE (utterance_id, token_index)
) WITHOUT ROWID;

-- Curated derived rows for longer/review-worthy speechless spans.
CREATE TABLE non_speech_context_span (
    id TEXT NOT NULL PRIMARY KEY,
    transcript_version_id TEXT NOT NULL,
    source_clip_id TEXT NOT NULL,
    ordinal INTEGER NOT NULL CHECK (ordinal >= 0),
    span_kind TEXT NOT NULL CHECK (span_kind IN ('speechless', 'visual_only')),
    start_us INTEGER NOT NULL CHECK (start_us >= 0),
    end_us INTEGER NOT NULL CHECK (end_us > start_us),
    display_status TEXT NOT NULL CHECK (display_status IN ('shown', 'not_shown')),
    display_reason TEXT,
    created_at TEXT NOT NULL,
    FOREIGN KEY (transcript_version_id) REFERENCES transcript_version(id) ON DELETE CASCADE,
    FOREIGN KEY (source_clip_id) REFERENCES source_clip(id) ON DELETE CASCADE,
    UNIQUE (transcript_version_id, source_clip_id, start_us, end_us)
) WITHOUT ROWID;

-- Each sealed revision contains all current utterance text overlays.
CREATE TABLE transcript_correction_revision (
    id TEXT NOT NULL PRIMARY KEY,
    transcript_version_id TEXT NOT NULL,
    revision_number INTEGER NOT NULL CHECK (revision_number >= 1),
    parent_revision_id TEXT,
    created_by TEXT NOT NULL CHECK (created_by IN ('creator', 'system')),
    created_at TEXT NOT NULL,
    sealed_at TEXT NOT NULL,
    FOREIGN KEY (transcript_version_id) REFERENCES transcript_version(id) ON DELETE CASCADE,
    FOREIGN KEY (parent_revision_id) REFERENCES transcript_correction_revision(id) ON DELETE RESTRICT,
    UNIQUE (transcript_version_id, revision_number)
) WITHOUT ROWID;

CREATE TABLE transcript_correction (
    id TEXT NOT NULL PRIMARY KEY,
    correction_revision_id TEXT NOT NULL,
    utterance_id TEXT NOT NULL,
    original_text_snapshot TEXT NOT NULL,
    corrected_text TEXT NOT NULL,
    created_at TEXT NOT NULL,
    FOREIGN KEY (correction_revision_id) REFERENCES transcript_correction_revision(id) ON DELETE CASCADE,
    FOREIGN KEY (utterance_id) REFERENCES utterance(id) ON DELETE CASCADE,
    UNIQUE (correction_revision_id, utterance_id)
) WITHOUT ROWID;

-- --------------------------------------------------------------------------
-- Analysis, processing, recommendations, and review state
-- --------------------------------------------------------------------------

CREATE TABLE analysis_run (
    id TEXT NOT NULL PRIMARY KEY,
    recording_session_id TEXT NOT NULL,
    sequence_revision_id TEXT NOT NULL,
    transcript_version_id TEXT NOT NULL,
    correction_revision_id TEXT,
    parent_analysis_run_id TEXT,
    run_kind TEXT NOT NULL CHECK (run_kind IN ('clean_analysis', 'story_cut_generation', 'reanalysis')),
    analysis_configuration_version TEXT NOT NULL,
    model_provider TEXT NOT NULL,
    model_name TEXT NOT NULL,
    target_min_us INTEGER,
    target_max_us INTEGER,
    requested_at TEXT NOT NULL,
    sealed_at TEXT,
    FOREIGN KEY (recording_session_id) REFERENCES recording_session(id) ON DELETE CASCADE,
    FOREIGN KEY (sequence_revision_id) REFERENCES sequence_revision(id) ON DELETE CASCADE,
    FOREIGN KEY (transcript_version_id) REFERENCES transcript_version(id) ON DELETE CASCADE,
    FOREIGN KEY (correction_revision_id) REFERENCES transcript_correction_revision(id) ON DELETE RESTRICT,
    FOREIGN KEY (parent_analysis_run_id) REFERENCES analysis_run(id) ON DELETE RESTRICT,
    CHECK ((target_min_us IS NULL AND target_max_us IS NULL) OR (target_min_us > 0 AND target_max_us >= target_min_us))
) WITHOUT ROWID;

-- Mutable stage status; terminal rows are retained for recovery/audit.
CREATE TABLE processing_stage (
    id TEXT NOT NULL PRIMARY KEY,
    project_id TEXT NOT NULL,
    analysis_run_id TEXT,
    transcription_run_id TEXT,
    retry_of_stage_id TEXT,
    stage_kind TEXT NOT NULL CHECK (stage_kind IN (
        'import', 'sequence_confirmation', 'audio_extraction', 'audio_upload',
        'transcription', 'utterance_segmentation', 'take_analysis',
        'clean_cut_generation', 'story_cut_generation', 'local_render'
    )),
    attempt INTEGER NOT NULL DEFAULT 1 CHECK (attempt >= 1),
    status TEXT NOT NULL CHECK (status IN ('pending', 'running', 'succeeded', 'failed', 'cancelled')),
    progress REAL CHECK (progress IS NULL OR (progress >= 0.0 AND progress <= 1.0)),
    input_fingerprint TEXT,
    output_ref_json TEXT,
    error_code TEXT,
    error_message TEXT,
    created_at TEXT NOT NULL,
    started_at TEXT,
    completed_at TEXT,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (project_id) REFERENCES project(id) ON DELETE CASCADE,
    FOREIGN KEY (analysis_run_id) REFERENCES analysis_run(id) ON DELETE CASCADE,
    FOREIGN KEY (transcription_run_id) REFERENCES transcription_run(id) ON DELETE CASCADE,
    FOREIGN KEY (retry_of_stage_id) REFERENCES processing_stage(id) ON DELETE SET NULL,
    CHECK (analysis_run_id IS NULL OR transcription_run_id IS NULL)
) WITHOUT ROWID;

-- Immutable AI take grouping for one analysis run.
CREATE TABLE take_group (
    id TEXT NOT NULL PRIMARY KEY,
    analysis_run_id TEXT NOT NULL,
    transcript_version_id TEXT NOT NULL,
    group_ordinal INTEGER NOT NULL CHECK (group_ordinal >= 0),
    grouping_confidence REAL CHECK (grouping_confidence IS NULL OR (grouping_confidence >= 0.0 AND grouping_confidence <= 1.0)),
    locality_evidence_json TEXT,
    progression_evidence_json TEXT,
    created_at TEXT NOT NULL,
    FOREIGN KEY (analysis_run_id) REFERENCES analysis_run(id) ON DELETE CASCADE,
    FOREIGN KEY (transcript_version_id) REFERENCES transcript_version(id) ON DELETE CASCADE,
    UNIQUE (analysis_run_id, group_ordinal)
) WITHOUT ROWID;

CREATE TABLE take_group_candidate (
    id TEXT NOT NULL PRIMARY KEY,
    take_group_id TEXT NOT NULL,
    utterance_id TEXT NOT NULL,
    candidate_ordinal INTEGER NOT NULL CHECK (candidate_ordinal >= 0),
    semantic_similarity REAL CHECK (semantic_similarity IS NULL OR (semantic_similarity >= 0.0 AND semantic_similarity <= 1.0)),
    delivery_score REAL CHECK (delivery_score IS NULL OR (delivery_score >= 0.0 AND delivery_score <= 1.0)),
    completeness_score REAL CHECK (completeness_score IS NULL OR (completeness_score >= 0.0 AND completeness_score <= 1.0)),
    candidate_metadata_json TEXT,
    created_at TEXT NOT NULL,
    FOREIGN KEY (take_group_id) REFERENCES take_group(id) ON DELETE CASCADE,
    FOREIGN KEY (utterance_id) REFERENCES utterance(id) ON DELETE CASCADE,
    UNIQUE (take_group_id, candidate_ordinal),
    UNIQUE (take_group_id, utterance_id),
    UNIQUE (id, take_group_id)
) WITHOUT ROWID;

CREATE TABLE take_group_recommendation (
    id TEXT NOT NULL PRIMARY KEY,
    take_group_id TEXT NOT NULL UNIQUE,
    candidate_id TEXT NOT NULL,
    reason_code TEXT NOT NULL,
    recommendation_score REAL CHECK (recommendation_score IS NULL OR (recommendation_score >= 0.0 AND recommendation_score <= 1.0)),
    created_at TEXT NOT NULL,
    FOREIGN KEY (take_group_id) REFERENCES take_group(id) ON DELETE CASCADE,
    FOREIGN KEY (candidate_id, take_group_id) REFERENCES take_group_candidate(id, take_group_id) ON DELETE RESTRICT
) WITHOUT ROWID;

-- Immutable AI recommendation, including non-applied hypotheses.
CREATE TABLE ai_recommendation (
    id TEXT NOT NULL PRIMARY KEY,
    analysis_run_id TEXT NOT NULL,
    recommendation_ordinal INTEGER NOT NULL CHECK (recommendation_ordinal >= 0),
    recommendation_kind TEXT NOT NULL CHECK (recommendation_kind IN ('clean_exclusion', 'take_selection', 'story_removal', 'possible_alternatives')),
    recommended_action TEXT NOT NULL CHECK (recommended_action IN ('exclude', 'select_take', 'suggest')),
    confidence REAL CHECK (confidence IS NULL OR (confidence >= 0.0 AND confidence <= 1.0)),
    severity TEXT CHECK (severity IS NULL OR severity IN ('mechanical', 'editorial', 'uncertain')),
    reason_code TEXT,
    reason_text TEXT,
    take_group_id TEXT,
    contiguous_start_utterance_id TEXT,
    contiguous_end_utterance_id TEXT,
    duration_delta_us INTEGER,
    details_json TEXT,
    created_at TEXT NOT NULL,
    FOREIGN KEY (analysis_run_id) REFERENCES analysis_run(id) ON DELETE CASCADE,
    FOREIGN KEY (take_group_id) REFERENCES take_group(id) ON DELETE RESTRICT,
    FOREIGN KEY (contiguous_start_utterance_id) REFERENCES utterance(id) ON DELETE RESTRICT,
    FOREIGN KEY (contiguous_end_utterance_id) REFERENCES utterance(id) ON DELETE RESTRICT,
    UNIQUE (analysis_run_id, recommendation_ordinal)
) WITHOUT ROWID;

CREATE TABLE recommendation_target_utterance (
    recommendation_id TEXT NOT NULL,
    utterance_id TEXT NOT NULL,
    target_ordinal INTEGER NOT NULL CHECK (target_ordinal >= 0),
    target_role TEXT NOT NULL CHECK (target_role IN ('candidate', 'story_section_member', 'possible_alternative')),
    PRIMARY KEY (recommendation_id, utterance_id),
    FOREIGN KEY (recommendation_id) REFERENCES ai_recommendation(id) ON DELETE CASCADE,
    FOREIGN KEY (utterance_id) REFERENCES utterance(id) ON DELETE RESTRICT,
    UNIQUE (recommendation_id, target_ordinal)
) WITHOUT ROWID;

-- Mutable current review state; the recommendation itself is never changed.
CREATE TABLE recommendation_review_state (
    recommendation_id TEXT NOT NULL PRIMARY KEY,
    status TEXT NOT NULL DEFAULT 'unreviewed' CHECK (status IN ('unreviewed', 'accepted', 'rejected', 'ignored', 'deferred')),
    accepted_into_cut_variant_id TEXT,
    last_reviewed_at TEXT,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (recommendation_id) REFERENCES ai_recommendation(id) ON DELETE CASCADE,
    FOREIGN KEY (accepted_into_cut_variant_id) REFERENCES cut_variant(id) ON DELETE SET NULL
) WITHOUT ROWID;

CREATE TABLE recommendation_review_event (
    id TEXT NOT NULL PRIMARY KEY,
    recommendation_id TEXT NOT NULL,
    actor_type TEXT NOT NULL CHECK (actor_type IN ('creator', 'system')),
    status TEXT NOT NULL CHECK (status IN ('unreviewed', 'accepted', 'rejected', 'ignored', 'deferred')),
    cut_variant_id TEXT,
    details_json TEXT,
    created_at TEXT NOT NULL,
    FOREIGN KEY (recommendation_id) REFERENCES ai_recommendation(id) ON DELETE CASCADE,
    FOREIGN KEY (cut_variant_id) REFERENCES cut_variant(id) ON DELETE SET NULL
) WITHOUT ROWID;

-- --------------------------------------------------------------------------
-- Cut variants, resolved plans, edits, and exports
-- --------------------------------------------------------------------------

CREATE TABLE cut_variant (
    id TEXT NOT NULL PRIMARY KEY,
    project_id TEXT NOT NULL,
    recording_session_id TEXT NOT NULL,
    origin_analysis_run_id TEXT NOT NULL,
    parent_cut_variant_id TEXT,
    variant_kind TEXT NOT NULL CHECK (variant_kind IN ('ai_clean', 'ai_story', 'creator')),
    lifecycle_status TEXT NOT NULL CHECK (lifecycle_status IN ('draft', 'ready', 'archived')),
    display_name TEXT NOT NULL,
    target_min_us INTEGER,
    target_max_us INTEGER,
    state_revision INTEGER NOT NULL DEFAULT 0 CHECK (state_revision >= 0),
    resolved_duration_us INTEGER NOT NULL DEFAULT 0 CHECK (resolved_duration_us >= 0),
    resolved_plan_hash TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    sealed_at TEXT,
    FOREIGN KEY (project_id) REFERENCES project(id) ON DELETE CASCADE,
    FOREIGN KEY (recording_session_id) REFERENCES recording_session(id) ON DELETE CASCADE,
    FOREIGN KEY (origin_analysis_run_id) REFERENCES analysis_run(id) ON DELETE RESTRICT,
    FOREIGN KEY (parent_cut_variant_id) REFERENCES cut_variant(id) ON DELETE RESTRICT,
    CHECK ((target_min_us IS NULL AND target_max_us IS NULL) OR (target_min_us > 0 AND target_max_us >= target_min_us)),
    CHECK (variant_kind = 'creator' OR sealed_at IS NOT NULL),
    CHECK (variant_kind <> 'creator' OR parent_cut_variant_id IS NOT NULL)
) WITHOUT ROWID;

CREATE TABLE cut_variant_segment (
    id TEXT NOT NULL PRIMARY KEY,
    cut_variant_id TEXT NOT NULL,
    ordinal INTEGER NOT NULL CHECK (ordinal >= 0),
    plan_revision INTEGER NOT NULL CHECK (plan_revision >= 0),
    source_clip_id TEXT NOT NULL,
    source_start_us INTEGER NOT NULL CHECK (source_start_us >= 0),
    source_end_us INTEGER NOT NULL CHECK (source_end_us > source_start_us),
    semantic_kind TEXT NOT NULL CHECK (semantic_kind IN ('utterance', 'non_speech_context', 'bridge', 'other')),
    semantic_ref_id TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (cut_variant_id) REFERENCES cut_variant(id) ON DELETE CASCADE,
    FOREIGN KEY (source_clip_id) REFERENCES source_clip(id) ON DELETE RESTRICT,
    UNIQUE (cut_variant_id, ordinal)
) WITHOUT ROWID;

-- Current application state for recommendations in a particular cut.
CREATE TABLE cut_variant_recommendation (
    id TEXT NOT NULL PRIMARY KEY,
    cut_variant_id TEXT NOT NULL,
    recommendation_id TEXT NOT NULL,
    application_state TEXT NOT NULL CHECK (application_state IN ('applied', 'not_applied', 'overridden')),
    selected_take_candidate_id TEXT,
    decision_source TEXT NOT NULL CHECK (decision_source IN ('ai', 'creator')),
    updated_at TEXT NOT NULL,
    FOREIGN KEY (cut_variant_id) REFERENCES cut_variant(id) ON DELETE CASCADE,
    FOREIGN KEY (recommendation_id) REFERENCES ai_recommendation(id) ON DELETE RESTRICT,
    FOREIGN KEY (selected_take_candidate_id) REFERENCES take_group_candidate(id) ON DELETE RESTRICT,
    UNIQUE (cut_variant_id, recommendation_id)
) WITHOUT ROWID;

CREATE TABLE edit_session (
    id TEXT NOT NULL PRIMARY KEY,
    project_id TEXT NOT NULL,
    started_at TEXT NOT NULL,
    last_activity_at TEXT NOT NULL,
    closed_at TEXT,
    FOREIGN KEY (project_id) REFERENCES project(id) ON DELETE CASCADE
) WITHOUT ROWID;

-- Append-only audit/history. Current state is materialized in cut_variant* tables.
CREATE TABLE edit_operation (
    id TEXT NOT NULL PRIMARY KEY,
    project_id TEXT NOT NULL,
    cut_variant_id TEXT NOT NULL,
    edit_session_id TEXT,
    operation_number INTEGER NOT NULL CHECK (operation_number >= 1),
    operation_kind TEXT NOT NULL,
    actor_type TEXT NOT NULL CHECK (actor_type IN ('ai', 'creator', 'system')),
    analysis_run_id TEXT,
    recommendation_id TEXT,
    target_kind TEXT NOT NULL,
    target_id TEXT,
    before_state_json TEXT NOT NULL,
    after_state_json TEXT NOT NULL,
    inverse_of_operation_id TEXT,
    created_at TEXT NOT NULL,
    FOREIGN KEY (project_id) REFERENCES project(id) ON DELETE CASCADE,
    FOREIGN KEY (cut_variant_id) REFERENCES cut_variant(id) ON DELETE CASCADE,
    FOREIGN KEY (edit_session_id) REFERENCES edit_session(id) ON DELETE SET NULL,
    FOREIGN KEY (analysis_run_id) REFERENCES analysis_run(id) ON DELETE RESTRICT,
    FOREIGN KEY (recommendation_id) REFERENCES ai_recommendation(id) ON DELETE RESTRICT,
    FOREIGN KEY (inverse_of_operation_id) REFERENCES edit_operation(id) ON DELETE RESTRICT,
    UNIQUE (cut_variant_id, operation_number)
) WITHOUT ROWID;

CREATE TABLE export_record (
    id TEXT NOT NULL PRIMARY KEY,
    project_id TEXT NOT NULL,
    cut_variant_id TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('requested', 'running', 'completed', 'failed', 'cancelled')),
    output_format TEXT NOT NULL DEFAULT 'mp4',
    external_path_hint TEXT,
    stored_in_package INTEGER NOT NULL DEFAULT 0 CHECK (stored_in_package IN (0, 1)),
    output_fingerprint TEXT,
    output_size_bytes INTEGER CHECK (output_size_bytes IS NULL OR output_size_bytes >= 0),
    output_duration_us INTEGER CHECK (output_duration_us IS NULL OR output_duration_us >= 0),
    render_plan_hash TEXT NOT NULL,
    requested_at TEXT NOT NULL,
    started_at TEXT,
    completed_at TEXT,
    error_code TEXT,
    error_message TEXT,
    FOREIGN KEY (project_id) REFERENCES project(id) ON DELETE CASCADE,
    FOREIGN KEY (cut_variant_id) REFERENCES cut_variant(id) ON DELETE RESTRICT
) WITHOUT ROWID;

-- One mutable pointer row for the currently selected project state.
CREATE TABLE project_state (
    project_id TEXT NOT NULL PRIMARY KEY,
    current_sequence_revision_id TEXT,
    current_transcript_version_id TEXT,
    current_correction_revision_id TEXT,
    current_analysis_run_id TEXT,
    current_ai_clean_cut_id TEXT,
    current_ai_story_cut_id TEXT,
    current_creator_cut_id TEXT,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (project_id) REFERENCES project(id) ON DELETE CASCADE,
    FOREIGN KEY (current_sequence_revision_id) REFERENCES sequence_revision(id) ON DELETE RESTRICT,
    FOREIGN KEY (current_transcript_version_id) REFERENCES transcript_version(id) ON DELETE RESTRICT,
    FOREIGN KEY (current_correction_revision_id) REFERENCES transcript_correction_revision(id) ON DELETE RESTRICT,
    FOREIGN KEY (current_analysis_run_id) REFERENCES analysis_run(id) ON DELETE RESTRICT,
    FOREIGN KEY (current_ai_clean_cut_id) REFERENCES cut_variant(id) ON DELETE RESTRICT,
    FOREIGN KEY (current_ai_story_cut_id) REFERENCES cut_variant(id) ON DELETE RESTRICT,
    FOREIGN KEY (current_creator_cut_id) REFERENCES cut_variant(id) ON DELETE RESTRICT
) WITHOUT ROWID;

-- --------------------------------------------------------------------------
-- Indexes
-- --------------------------------------------------------------------------

CREATE INDEX idx_source_clip_project ON source_clip(project_id, imported_at);
CREATE INDEX idx_source_clip_location_status ON source_clip_location(availability_status, updated_at);
CREATE INDEX idx_source_relink_clip_time ON source_relink_event(source_clip_id, created_at);

CREATE INDEX idx_sequence_revision_session ON sequence_revision(recording_session_id, revision_number DESC);
CREATE INDEX idx_sequence_revision_status ON sequence_revision(recording_session_id, status);
CREATE INDEX idx_sequence_membership_revision_order ON sequence_membership(sequence_revision_id, ordinal);
CREATE INDEX idx_sequence_membership_clip ON sequence_membership(source_clip_id, sequence_revision_id);

CREATE INDEX idx_transcription_run_session ON transcription_run(recording_session_id, requested_at DESC);
CREATE INDEX idx_transcript_version_sequence ON transcript_version(sequence_revision_id, version_number DESC);
CREATE INDEX idx_utterance_version_order ON utterance(transcript_version_id, ordinal);
CREATE INDEX idx_utterance_range_clip_time ON utterance_source_range(source_clip_id, start_us, end_us);
CREATE INDEX idx_word_alignment_utterance_order ON word_alignment(utterance_id, token_index);
CREATE INDEX idx_word_alignment_clip_time ON word_alignment(source_clip_id, start_us, end_us);
CREATE INDEX idx_non_speech_version_display ON non_speech_context_span(transcript_version_id, display_status, ordinal);
CREATE INDEX idx_non_speech_clip_time ON non_speech_context_span(source_clip_id, start_us, end_us);
CREATE INDEX idx_correction_revision_version ON transcript_correction_revision(transcript_version_id, revision_number DESC);
CREATE INDEX idx_correction_utterance ON transcript_correction(utterance_id, correction_revision_id);

CREATE INDEX idx_analysis_run_session ON analysis_run(recording_session_id, requested_at DESC);
CREATE INDEX idx_analysis_run_transcript ON analysis_run(transcript_version_id, requested_at DESC);
CREATE INDEX idx_analysis_run_parent ON analysis_run(parent_analysis_run_id, requested_at);
CREATE INDEX idx_processing_project_status ON processing_stage(project_id, status, updated_at DESC);
CREATE INDEX idx_processing_analysis_status ON processing_stage(analysis_run_id, status, stage_kind);
CREATE INDEX idx_processing_transcription_status ON processing_stage(transcription_run_id, status, stage_kind);

CREATE INDEX idx_take_group_run_order ON take_group(analysis_run_id, group_ordinal);
CREATE INDEX idx_take_candidate_group_order ON take_group_candidate(take_group_id, candidate_ordinal);
CREATE INDEX idx_take_candidate_utterance ON take_group_candidate(utterance_id, take_group_id);

CREATE INDEX idx_recommendation_run_kind ON ai_recommendation(analysis_run_id, recommendation_kind, recommendation_ordinal);
CREATE INDEX idx_recommendation_take_group ON ai_recommendation(take_group_id);
CREATE INDEX idx_recommendation_target_utterance ON recommendation_target_utterance(utterance_id, recommendation_id);
CREATE INDEX idx_recommendation_review_status ON recommendation_review_state(status, updated_at);
CREATE INDEX idx_recommendation_review_event_rec ON recommendation_review_event(recommendation_id, created_at);

CREATE UNIQUE INDEX uq_ai_clean_cut_per_run
    ON cut_variant(origin_analysis_run_id)
    WHERE variant_kind = 'ai_clean';
CREATE UNIQUE INDEX uq_ai_story_cut_per_run
    ON cut_variant(origin_analysis_run_id)
    WHERE variant_kind = 'ai_story';
CREATE INDEX idx_cut_variant_project_kind ON cut_variant(project_id, variant_kind, updated_at DESC);
CREATE INDEX idx_cut_variant_analysis_kind ON cut_variant(origin_analysis_run_id, variant_kind);
CREATE INDEX idx_cut_variant_parent ON cut_variant(parent_cut_variant_id);
CREATE INDEX idx_cut_segment_variant_order ON cut_variant_segment(cut_variant_id, ordinal);
CREATE INDEX idx_cut_segment_source_time ON cut_variant_segment(source_clip_id, source_start_us, source_end_us);
CREATE INDEX idx_cut_recommendation_variant ON cut_variant_recommendation(cut_variant_id, application_state);
CREATE INDEX idx_cut_recommendation_rec ON cut_variant_recommendation(recommendation_id, cut_variant_id);
CREATE INDEX idx_edit_session_project ON edit_session(project_id, last_activity_at DESC);
CREATE INDEX idx_edit_operation_variant_order ON edit_operation(cut_variant_id, operation_number);
CREATE INDEX idx_edit_operation_target ON edit_operation(target_kind, target_id, created_at);
CREATE INDEX idx_edit_operation_recommendation ON edit_operation(recommendation_id, created_at);
CREATE INDEX idx_export_project_status ON export_record(project_id, status, requested_at DESC);
CREATE INDEX idx_export_variant_time ON export_record(cut_variant_id, requested_at DESC);
